import {
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  renameSync,
  rmSync,
  statSync,
} from 'node:fs';
import {dirname, join, relative} from 'node:path';

export const RUST_CRATE_DIRECTORY = './rust';
export const RUST_ABI_DIRECTORY = join(RUST_CRATE_DIRECTORY, 'src/abis');
export const RUST_ADDRESSES_DIRECTORY = join(RUST_CRATE_DIRECTORY, 'src/addresses');

export const RUST_GENERATED_WARNING =
  '// AUTOGENERATED - MANUAL CHANGES WILL BE REVERTED BY THE GENERATOR\n';

// https://doc.rust-lang.org/reference/keywords.html
const RUST_KEYWORDS = new Set([
  'as',
  'async',
  'await',
  'break',
  'const',
  'continue',
  'crate',
  'dyn',
  'else',
  'enum',
  'extern',
  'false',
  'fn',
  'for',
  'gen',
  'if',
  'impl',
  'in',
  'let',
  'loop',
  'match',
  'mod',
  'move',
  'mut',
  'pub',
  'ref',
  'return',
  'self',
  'Self',
  'static',
  'struct',
  'super',
  'trait',
  'true',
  'type',
  'unsafe',
  'use',
  'where',
  'while',
  'abstract',
  'become',
  'box',
  'do',
  'final',
  'macro',
  'override',
  'priv',
  'try',
  'typeof',
  'unsized',
  'virtual',
  'yield',
]);

/**
 * @dev Turns an address book key into a Rust identifier. Case is preserved so the Rust paths read
 * like the Solidity and TypeScript ones (`AaveV3Ethereum::ASSETS::USDC::A_TOKEN`).
 */
export function toRustIdent(key: string) {
  let ident = key.replace(/[^A-Za-z0-9_]/g, '_');
  if (!ident || /^\d/.test(ident)) ident = `_${ident}`;
  if (ident === '_') ident = '__';
  if (RUST_KEYWORDS.has(ident)) ident = `${ident}_`;
  return ident;
}

/**
 * @dev Converts an interface name like `IPoolAddressesProvider` into a module name like
 * `i_pool_addresses_provider`.
 */
export function toRustModuleName(name: string) {
  return toRustIdent(
    name
      .replace(/([a-z0-9])([A-Z])/g, '$1_$2')
      .replace(/([A-Z])([A-Z][a-z])/g, '$1_$2')
      .toLowerCase(),
  );
}

export function toRustString(value: string) {
  let escaped = '';
  for (const char of value) {
    const code = char.codePointAt(0)!;
    if (char === '\\') escaped += '\\\\';
    else if (char === '"') escaped += '\\"';
    else if (char === '\n') escaped += '\\n';
    else if (char === '\r') escaped += '\\r';
    else if (char === '\t') escaped += '\\t';
    else if (code < 0x20 || code === 0x7f) escaped += `\\u{${code.toString(16)}}`;
    else escaped += char;
  }
  return `"${escaped}"`;
}

/**
 * @dev Writes into a staging directory next to `directory`, then swaps it in, so a failed
 * generation never leaves a half-written directory behind.
 */
export async function replaceDirectory(
  directory: string,
  generate: (stagingDirectory: string) => Promise<void> | void,
) {
  mkdirSync(dirname(directory), {recursive: true});
  const stagingDirectory = mkdtempSync(join(dirname(directory), '.staging-'));

  try {
    await generate(stagingDirectory);
    rmSync(directory, {recursive: true, force: true});
    renameSync(stagingDirectory, directory);
  } catch (error) {
    rmSync(stagingDirectory, {recursive: true, force: true});
    throw error;
  }
}

function listFiles(directory: string, root = directory): string[] {
  return readdirSync(directory)
    .flatMap((entry) => {
      const path = join(directory, entry);
      return statSync(path).isDirectory() ? listFiles(path, root) : [relative(root, path)];
    })
    .sort();
}

/**
 * @dev Returns the files that differ between two directories, including files only one has.
 */
export function diffDirectories(currentDirectory: string, generatedDirectory: string) {
  const currentFiles = listFiles(currentDirectory);
  const generatedFiles = listFiles(generatedDirectory);
  const changedFiles = generatedFiles.filter(
    (file) =>
      !currentFiles.includes(file) ||
      readFileSync(join(currentDirectory, file), 'utf8') !==
        readFileSync(join(generatedDirectory, file), 'utf8'),
  );
  const extraFiles = currentFiles.filter((file) => !generatedFiles.includes(file));
  return [...changedFiles, ...extraFiles].sort();
}
